app.MapControllerRoute(
    name: "product-details",
    pattern: "Products/{id:int}",
    defaults: new { controller = "Products", action = "Details" });

// In a Razor view
<a href="@Url.RouteUrl("product-details", new { id = 5 })">
    View Product 5
</a>
<!-- Generates: /Products/5 -->

@Html.ActionLink(
    linkText: "View Product 5",
    actionName: "Details",
    controllerName: "Products",
    routeValues: new { id = 5 },
    htmlAttributes: new { @class = "btn btn-primary" }
)
<!-- Generates: <a href="/Products/Details/5" class="btn btn-primary">View Product 5</a> -->

public class ProductsController : Controller
{
    private readonly IEmailService _emailService;

    public ProductsController(IEmailService emailService)
    {
        _emailService = emailService;
    }

    [HttpPost]
    public IActionResult Create(Product product)
    {
        if (!ModelState.IsValid) return View(product);

        _repo.Add(product);

        // Generate a URL to send in a confirmation email
        var productUrl = Url.Action(
            "Details",
            "Products",
            new { id = product.Id },
            protocol: Request.Scheme // includes http:// or https://
        );

        _emailService.SendConfirmation(product.OwnerEmail, productUrl);

        return RedirectToAction(nameof(Index));
    }
}

public class HomeController : Controller
{
    public IActionResult CurrentUrlInfo()
    {
        var request = HttpContext.Request;

        ViewBag.Path = request.Path;           // /Products/Details/5
        ViewBag.QueryString = request.QueryString.Value; // ?ref=homepage
        ViewBag.Host = request.Host.Value;     // localhost:5001
        ViewBag.Scheme = request.Scheme;       // https
        ViewBag.FullUrl = $"{request.Scheme}://{request.Host}{request.Path}";

        return View();
    }
}
